package com.auditlog.api.controller;
import com.auditlog.api.dto.CreateRedactionRequest; import com.auditlog.api.response.ApiResponse; import com.auditlog.application.service.PayloadRedactionService; import jakarta.validation.Valid; import org.slf4j.MDC; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/audit/events") public class PayloadRedactionController { private final PayloadRedactionService service; public PayloadRedactionController(PayloadRedactionService s){service=s;} @PostMapping("/{eventId}/redactions") public ResponseEntity<ApiResponse<Map<String,UUID>>> redact(@PathVariable UUID eventId,@Valid @RequestBody CreateRedactionRequest request){ UUID action=service.redact(eventId,request.jsonPointer(),request.reason(),request.policyVersion(),request.authorizedBy()); return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success(Map.of("redactionEventId",action),MDC.get("traceId"))); } }
